body:
{getAlertContent()}
{showContactSupport && !!contactSupportText && (
  <Link href="/support-center-ui">{contactSupportText}</Link>
)}
{showContactSupport && !contactSupportText && (
  // Default contact support text
  <>
    If the problem persists,{" "}
    <Link
      href="/support-center-ui"
      sx={
        // Only need text color override when variant is filled
        props.variant === "filled" && {
          // TODO: Remove !important once krome.css is retired. It's applying unwanted .tebra.tebra a class
          color: "inherit !important",
          textDecorationColor: "inherit",
        }
      }
    >
      contact Tebra Support.
    </Link>
  </>
)}

{isThisAppointmentOptionDisplayed && (
  <FormControlLabel
    value={AppointmentUpdateType.OCCURRENCE}
    label="This appointment"
    control={<Radio />}
  />
)}
{isThisAndFollowingOptionDisplayed && (
  <FormControlLabel
    value={AppointmentUpdateType.SUBSEQUENT}
    label="This appointment and following appointments"
    control={<Radio />}
  />
)}
<FormControlLabel
  value={AppointmentUpdateType.SERIES}
  label="All appointments in the series"
  control={<Radio />}
/>

{hasEditLookupError
  ? "We couldn't load this event. Try again or close the drawer."
  : "This event could not be found. It may have been deleted or moved."}

{visibleOptions.map(({ type, label }) => (
  <Button
    aria-pressed={selectedType === type}
    key={type}
    startIcon={
      selectedType === type ? <CheckIcon fontSize="small" /> : null
    }
    sx={selectedType === type ? selectedStyle : {}}
    onClick={() => onChange(type)}
    data-testid={`event-type-selector-${type}`}
  >
    {label}
  </Button>
))}

{window === SchedulingWindow.DAY && <ScheduleIcon fontSize="small" />}
{window === SchedulingWindow.WEEK && (
  <CalendarViewWeekIcon fontSize="small" />
)}
{window === SchedulingWindow.MONTH && (
  <CalendarViewMonthIcon fontSize="small" />
)}
<Typography marginLeft={0.5}>{buttonText}</Typography>

{bookingState === "booking" ? (
  <CircularProgress size={24} />
) : selectedSlot ? (
  `Book ${selectedSlot.time} on ${formatDateHeader(
    selectedSlot.date
  )}`
) : (
  "Select a slot"
)}

{`We found ${errorCount} ${
  errorCount > 1 ? "errors" : "error"
}. Please correct ${errorCount > 1 ? "them" : "it"} to proceed.`}

{processingError
  ? "Unable to process payments at this time, please try again in a few moments."
  : "Unable to process payments credit cards at this time."}

{/* Bold */}
<RibbonIconButton
  aria-label="Bold"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleBold().run()
    )
  }
>
  <FormatBoldIcon />
</RibbonIconButton>
{/* Italic */}
<RibbonIconButton
  aria-label="Italic"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleItalic().run()
    )
  }
>
  <FormatItalicIcon />
</RibbonIconButton>
{/* Underline */}
<RibbonIconButton
  aria-label="Underline"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleUnderline().run()
    )
  }
>
  <FormatUnderlinedIcon />
</RibbonIconButton>
{/* Strike */}
<RibbonIconButton
  aria-label="Strike"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleStrike().run()
    )
  }
>
  <FormatStrikethroughIcon />
</RibbonIconButton>

{/* Bullet List */}
<RibbonIconButton
  aria-label="Bullet List"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleBulletList().run()
    )
  }
>
  <FormatListBulletedIcon />
</RibbonIconButton>
{/* Ordered List */}
<RibbonIconButton
  aria-label="Ordered List"
  disabled={isReadOnly}
  onClick={() =>
    applyToggle(() =>
      (editor as any)?.chain?.().focus().toggleOrderedList().run()
    )
  }
>
  <FormatListNumberedIcon />
</RibbonIconButton>

{!showRefineFiltersMessage && (
  <Box sx={{ py: 0.5 }}>
    Displayable cap reached. Fine-tune your view by{" "}
    <Link
      sx={{ cursor: "pointer" }}
      onClick={() => setIsFilterDrawerOpen(true)}
    >
      adding filters
    </Link>
    .
  </Box>
)}
{showRefineFiltersMessage && (
  <Box
    sx={{
      display: "flex",
      alignItems: "center",
      gap: 0.5,
      justifyContent: "space-between",
    }}
  >
    Report showing partial dataset. Consider refining your filters.
    <Button
      size="small"
      variant="text"
      onClick={() => setIsFilterDrawerOpen(true)}
    >
      REFINE FILTERS
    </Button>
  </Box>
)}

        {/* Left side: name + optional chip */}

        <Typography variant="body1" noWrap>
          <Typography
            component="span"
            fontWeight={theme.typography.fontWeightBold}
            color={theme.palette.text.primary}
          >
            {patientGroup.name}
          </Typography>{" "}
          <Typography
            variant="body1"
            color={theme.palette.text.disabled}
            fontWeight="normal"
            component="span"
          >
            ({patientGroup.count} Patients)
          </Typography>
        </Typography>

        {patientGroup.preset && (
          <Chip label="Preset" size="small" sx={{ cursor: "inherit" }} />
        )}

{recommendedSigs.map((sig) => (
  <FormControlLabel
    value={sig}
    label={sig}
    control={<Radio sx={{ padding: 1 }} />}
    key={sig}
  />
))}

{icdCode.isFavorite === true && (
  <FavoritesFilledIcon color="primary" />
)}
{icdCode.isFavorite === false && (
  <FavoritesOutlinedIcon
    sx={{
      color: "primary.light",
      "&:hover": { color: "primary.main" },
    }}
  />
)}
{icdCode.isFavorite === undefined && <AttentionFilledIcon />}

                  {calculatedSigs?.map((calculatedSig: CalculatedSig) => {
                    let sigLabel = calculatedSig.doseIsCalculated
                      ? calculatedSig.calculatedSigText
                      : calculatedSig.sig.sigText;

                    sigLabel = sigLabel.replace(
                      "<insert_calc_doseform_amt>",
                      "{{Include calculated dose here}}",
                    );

                    return (
                      <FormControlLabel
                        // eslint-disable-next-line
                        sx={{
                          margin: 0,
                          padding: 0,
                          borderBottom: "1px solid",
                          borderColor: "core.light",
                          width: "100%",
                        }}
                        value={sigLabel}
                        label={
                          <Typography variant="body2">{sigLabel}</Typography>
                        }
                        control={
                          <Radio sx={{ paddingRight: 1 }} size="small" />
                        }
                        key={sigLabel}
                      />
                    );
                  })}

{q.answers.map((a) => (
  <FormControlLabel
    key={a.id}
    value={a.id}
    control={<Radio />}
    label={
      <span
        style={{
          color: "inherit",
          fontWeight: 500,
          cursor: "pointer",
          ...(a.underlined
            ? { textDecoration: "underline" }
            : {}),
        }}
      >
        {a.text}
      </span>
    }
    sx={{ mb: 0, ml: 0, pl: 0, cursor: "default" }}
  />
))}

{
  "Location list failed to load. Please save your progress and load the page again."
}

{options?.map((option) => (
  <StyledFormControlLabel
    key={option.id}
    value={option.id}
    pdfPrintMode={pdfPrintMode}
    control={<Radio size="small" />}
    label={option.name}
  />
))}

{`Insurance payments may already be created automatically from ERA
posting. It's recommended to check before adding a new one to avoid
duplicates.`}

{hasFilters ? (
  <>
    Report showing partial dataset. Report features will not have the
    expected behavior due to your current criteria. Consider refining
    your {renderFiltersLink()}.{renderFiltersButton("VIEW FILTERS")}
  </>
) : (
  <>
    Total records must be under {dataLimit} to utilize all report
    features. Fine-tune your report using {renderFiltersLink()}.
    {renderFiltersButton("OPEN FILTERS")}
  </>
)}
